out = [{"id": f"s{i+1:02d}_{k}", "key": k, "text": t} for i, (k, t) in enumerate(segs)]
json.dump(out, open("script/narration.json", "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print(len(out), "segments,", sum(len(s["text"]) for s in out), "characters")
